import json

def exists(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.exists', json.dumps({'path': path}))['returnValue']

def duplicate(source, target):
    if not exists(target) and not execute_tool('editor_toolset.toolsets.asset.AssetTools.duplicate', json.dumps({'path': source, 'new_path': target}))['returnValue']:
        raise RuntimeError('duplicate failed: ' + target)

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def nodes(bt):
    return execute_tool('aimodule_toolset.toolsets.behavior_tree.BehaviorTreeTools.list_nodes', json.dumps({'behavior_tree': bt}))['returnValue']

def list_props(obj):
    return json.loads(execute_tool('editor_toolset.toolsets.object.ObjectTools.list_properties', json.dumps({'instance': obj}))['returnValue'])

def get(obj, names):
    return json.loads(execute_tool('editor_toolset.toolsets.object.ObjectTools.get_properties', json.dumps({'instance': obj, 'properties': names}))['returnValue'])

def setv(obj, values):
    if not execute_tool('editor_toolset.toolsets.object.ObjectTools.set_properties', json.dumps({'instance': obj, 'values': json.dumps(values)}))['returnValue']:
        raise RuntimeError('set properties failed: ' + str(obj))

def compile_bp(bp):
    execute_tool('editor_toolset.toolsets.blueprint.BlueprintTools.compile_blueprint', json.dumps({'blueprint': bp, 'warnings_as_errors': True}))

def save(paths):
    if not execute_tool('editor_toolset.toolsets.asset.AssetTools.save_assets', json.dumps({'asset_paths': paths}))['returnValue']:
        raise RuntimeError('save failed')

def run():
    controller_source = '/ShooterCore/Bot/B_AI_Controller_LyraShooter'
    bt_source = '/ShooterCore/Bot/BT/BT_Lyra_Shooter_Bot'
    eqs_source = '/ShooterCore/Bot/EQS/EQS_MoveAgainstEnnemy'
    role_names = ['Patrol', 'Flanker', 'Elite']
    paths = []
    duplicate(eqs_source, '/ExtractionOps/AI/EQS/EQS_ExtractionFlank')
    paths.append('/ExtractionOps/AI/EQS/EQS_ExtractionFlank')
    for role in role_names:
        controller = '/ExtractionOps/AI/B_AI_Controller_Extraction' + role
        bt = '/ExtractionOps/AI/BT/BT_Extraction' + role
        duplicate(controller_source, controller)
        duplicate(bt_source, bt)
        cdo = {'refPath': controller + '.Default__B_AI_Controller_Extraction' + role + '_C'}
        setv(cdo, {'bTAsset': {'refPath': bt + '.BT_Extraction' + role}})
        compile_bp(load(controller))
        paths += [controller, bt]
    flanker_bt = load('/ExtractionOps/AI/BT/BT_ExtractionFlanker')
    rewired = 0
    already_rewired = 0
    for node in nodes(flanker_bt):
        if 'eQSRequest' not in list_props(node):
            continue
        request = get(node, ['eQSRequest']).get('eQSRequest')
        if request and 'EQS_MoveAgainstEnnemy' in str(request.get('queryTemplate')):
            request['queryTemplate'] = {'refPath': '/ExtractionOps/AI/EQS/EQS_ExtractionFlank.EQS_ExtractionFlank'}
            setv(node, {'eQSRequest': request})
            rewired += 1
        elif request and 'EQS_ExtractionFlank' in str(request.get('queryTemplate')):
            already_rewired += 1
    if rewired + already_rewired != 1:
        raise RuntimeError('expected one flank EQS node, got ' + str(rewired + already_rewired))
    save(paths)
    return {'assets': paths, 'flankNodesRewired': rewired, 'alreadyRewired': already_rewired}
